module rv32i_exec(input [31:0] instr, input [31:0] pc, input [31:0] rs1, input [31:0] rs2,
  input [31:0] mem_rdata,
  output reg rd_we, output reg [31:0] rd_val, output reg [31:0] next_pc,
  output [31:0] mem_addr, output reg [31:0] mem_wdata, output reg [3:0] mem_wstrb,
  output reg illegal, output reg misaligned);
  wire [6:0] opc = instr[6:0];
  wire [2:0] f3 = instr[14:12];
  wire [6:0] f7 = instr[31:25];
  wire [31:0] immI = {{20{instr[31]}}, instr[31:20]};
  wire [31:0] immS = {{20{instr[31]}}, instr[31:25], instr[11:7]};
  wire [31:0] immB = {{19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0};
  wire [31:0] immU = {instr[31:12], 12'b0};
  wire [31:0] immJ = {{11{instr[31]}}, instr[31], instr[19:12], instr[20], instr[30:21], 1'b0};
  wire is32 = &instr[1:0];
  wire isLUI = is32 & (opc[6:2]==5'b01101);
  wire isAUI = is32 & (opc[6:2]==5'b00101);
  wire isJAL = is32 & (opc[6:2]==5'b11011);
  wire isJALR = is32 & (opc[6:2]==5'b11001);
  wire isBR = is32 & (opc[6:2]==5'b11000);
  wire isLD = is32 & (opc[6:2]==5'b00000);
  wire isST = is32 & (opc[6:2]==5'b01000);
  wire isOPI = is32 & (opc[6:2]==5'b00100);
  wire isOP = is32 & (opc[6:2]==5'b01100);
  wire f7z = (f7==7'b0000000);
  wire f7s = (f7==7'b0100000);
  wire legJALR = (f3==3'b000);
  wire legBR = (f3[2:1]!=2'b01);
  wire legLD = (f3==3'b000)|(f3==3'b001)|(f3==3'b010)|(f3==3'b100)|(f3==3'b101);
  wire legST = (f3==3'b000)|(f3==3'b001)|(f3==3'b010);
  wire legOPI = (f3==3'b001) ? f7z : (f3==3'b101) ? (f7z|f7s) : 1'b1;
  wire legOP = f7z | (f7s & ((f3==3'b000)|(f3==3'b101)));
  wire legal = isLUI|isAUI|isJAL|(isJALR&legJALR)|(isBR&legBR)|(isLD&legLD)|(isST&legST)|(isOPI&legOPI)|(isOP&legOP);
  wire [31:0] ma = rs1 + (isST ? immS : immI);
  assign mem_addr = ma;
  wire [1:0] la = ma[1:0];
  wire mis = (isLD|isST) & (((f3[1:0]==2'b01) & la[0]) | ((f3[1]) & (la!=2'b00)));
  // ALU
  wire [31:0] opB = (isOP|isBR) ? rs2 : immI;
  wire sub = isOP & f7s & (f3==3'b000);
  wire [31:0] addr_res = sub ? rs1 - opB : rs1 + opB;
  wire [4:0] sh = isOP ? rs2[4:0] : instr[24:20];
  wire left = ~f3[2];
  wire [31:0] rv, rsh, sres;
  genvar gi;
  generate for (gi=0;gi<32;gi=gi+1) begin : rvg
    assign rv[gi] = rs1[31-gi];
    assign sres[gi] = left ? rsh[31-gi] : rsh[gi];
  end endgenerate
  wire [31:0] sin = left ? rv : rs1;
  wire [32:0] sx = {(~left & instr[30] & rs1[31]), sin};
  assign rsh = $signed(sx) >>> sh;
  wire [31:0] sll = sres; wire [31:0] srl = sres; wire [31:0] sra = sres;
  wire lts = $signed(rs1) < $signed(opB);
  wire ltu = rs1 < opB;
  reg [31:0] alu;
  always @* begin
    case (f3)
      3'b000: alu = addr_res;
      3'b001: alu = sll;
      3'b010: alu = {31'b0, lts};
      3'b011: alu = {31'b0, ltu};
      3'b100: alu = rs1 ^ opB;
      3'b101: alu = instr[30] ? sra : srl;
      3'b110: alu = rs1 | opB;
      default: alu = rs1 & opB;
    endcase
  end
  // branches
  wire eq = (rs1 == opB);
  wire blt = lts;
  wire bltu = ltu;
  reg taken;
  always @* begin
    case (f3)
      3'b000: taken = eq;
      3'b001: taken = ~eq;
      3'b100: taken = blt;
      3'b101: taken = ~blt;
      3'b110: taken = bltu;
      default: taken = ~bltu;
    endcase
  end
  // load data
  wire [31:0] lw = mem_rdata >> {la, 3'b000};
  reg [31:0] ldv;
  always @* begin
    case (f3)
      3'b000: ldv = {{24{lw[7]}}, lw[7:0]};
      3'b001: ldv = {{16{lw[15]}}, lw[15:0]};
      3'b100: ldv = {24'b0, lw[7:0]};
      3'b101: ldv = {16'b0, lw[15:0]};
      default: ldv = lw;
    endcase
  end
  wire [31:0] pc4 = pc + 32'd4;
  wire [31:0] tgt = pc + (isJAL ? immJ : immB);
  always @* begin
    rd_we = 1'b0; rd_val = alu; next_pc = pc4; mem_wstrb = 4'b0;
    mem_wdata = rs2 << {la, 3'b000};
    illegal = ~legal; misaligned = 1'b0;
    if (legal) begin
      if (isLUI) begin rd_we = 1; rd_val = immU; end
      else if (isAUI) begin rd_we = 1; rd_val = pc + immU; end
      else if (isJAL) begin rd_we = 1; rd_val = pc4; next_pc = tgt; end
      else if (isJALR) begin rd_we = 1; rd_val = pc4; next_pc = {ma[31:1], 1'b0}; end
      else if (isBR) begin if (taken) next_pc = tgt; end
      else if (isLD) begin
        if (mis) misaligned = 1; else begin rd_we = 1; rd_val = ldv; end
      end else if (isST) begin
        if (mis) misaligned = 1;
        else mem_wstrb = (f3[1] ? 4'b1111 : f3[0] ? 4'b0011 : 4'b0001) << la;
      end else begin rd_we = 1; rd_val = alu; end
    end
  end
endmodule

module rv32i_core(input clk, input rst_n,
  output [31:0] imem_addr, output [31:0] dmem_addr, output [31:0] dmem_wdata, output [3:0] dmem_wstrb,
  input [31:0] imem_rdata, input [31:0] dmem_rdata);
  reg [31:0] pc;
  reg [31:0] rf [1:31];
  wire [4:0] ra = imem_rdata[19:15];
  wire [4:0] rb = imem_rdata[24:20];
  wire [4:0] rd = imem_rdata[11:7];
  wire [31:0] r1 = (ra == 5'd0) ? 32'd0 : rf[ra];
  wire [31:0] r2 = (rb == 5'd0) ? 32'd0 : rf[rb];
  wire we, ill, mis; wire [31:0] rdv, npc;
  rv32i_exec ex(.instr(imem_rdata), .pc(pc), .rs1(r1), .rs2(r2), .mem_rdata(dmem_rdata),
    .rd_we(we), .rd_val(rdv), .next_pc(npc), .mem_addr(dmem_addr), .mem_wdata(dmem_wdata),
    .mem_wstrb(dmem_wstrb), .illegal(ill), .misaligned(mis));
  assign imem_addr = pc;
  integer i;
  always @(posedge clk) begin
    if (!rst_n) begin
      pc <= 32'd0;
      for (i = 1; i < 32; i = i + 1) rf[i] <= 32'd0;
    end else begin
      pc <= npc;
      if (we && rd != 5'd0) rf[rd] <= rdv;
    end
  end
endmodule
